//! The typed AST generator of `cargo xtask codegen` (epic #1219, #1221 item
//! i), modelled on rust-analyzer's sourcegen: each language's `.ungram`
//! (`crates/opentide-<lang>/src/<lang>.ungram`) becomes
//! `crates/opentide-<lang>/src/generated/ast.rs`, committed and checked by
//! `codegen --check`.
//!
//! The generated file holds, over `rowan` trees through
//! `opentide_parse::ast`:
//!
//! - a struct per node and an enum per `A = B | C` choice of nodes, each an
//!   `AstNode`, with an accessor per child: a node (`Option<T>`, or
//!   `AstChildren<T>` when the rule repeats it), a token (`<name>_token`),
//!   or whatever a label (`lhs:Expr`, `op:('+' | '-')`) names;
//! - `RULES`, each node kind's rule as data for
//!   `opentide_parse::conformance`.
//!
//! The language crate supplies `Lang` (its `rowan::Language`), `SyntaxKind`
//! (a variant per node, `UPPER_SNAKE` of its name), `SyntaxNode`,
//! `SyntaxToken` and the `T!` macro mapping each token of the grammar
//! (`T![where]`, `T!['(']`) to its kind.
//!
//! Where the generator cannot name a child unambiguously (a node type twice
//! in one rule, outside a repetition, without labels) it refuses, naming
//! the rule: label the occurrences, or hand-write the accessor.

use std::collections::{BTreeMap, BTreeSet};
use std::io::Write;
use std::path::Path;
use std::process::{Command, Stdio};

use anyhow::{Context, Result, anyhow, bail};
use ungrammar::{Grammar, Node, Rule, Token};

/// The first line of every generated file; a file that has it and no
/// grammar left is stale.
pub const MARKER: &str = "// @generated by `cargo xtask codegen`";

/// Grammars outside `crates/opentide-<lang>/src`, as `(grammar, directory
/// holding generated/ast.rs)`: the toolkit's own test language.
const EXTRA: [(&str, &str); 1] = [(
    "crates/opentide-parse/tests/ast_fixture/fixture.ungram",
    "crates/opentide-parse/tests/ast_fixture",
)];

/// Writes (or, with `check`, compares) every generated AST under `root`;
/// the problems, one per stale or missing file.
pub fn sync(root: &Path, check: bool) -> Result<Vec<String>> {
    let mut stale = Vec::new();
    let mut jobs: Vec<(String, String)> = EXTRA
        .iter()
        .filter(|(grammar, _)| root.join(grammar).is_file())
        .map(|(grammar, dir)| ((*grammar).to_owned(), format!("{dir}/generated/ast.rs")))
        .collect();
    let crates = root.join("crates");
    for entry in std::fs::read_dir(&crates).with_context(|| format!("read {}", crates.display()))? {
        let name = entry?.file_name().to_string_lossy().into_owned();
        let Some(lang) = name.strip_prefix("opentide-") else {
            continue;
        };
        let dir = format!("crates/{name}/src");
        let grammar = format!("{dir}/{lang}.ungram");
        let output = format!("{dir}/generated/ast.rs");
        if root.join(&grammar).is_file() {
            jobs.push((grammar, output));
        } else if std::fs::read_to_string(root.join(&output))
            .is_ok_and(|text| text.starts_with(MARKER))
        {
            stale.push(format!("{output}: generated from {grammar}, which is gone"));
        }
    }
    let mut problems = stale;
    for (grammar, output) in jobs {
        let source = std::fs::read_to_string(root.join(&grammar))
            .with_context(|| format!("read {grammar}"))?;
        let text = format_rust(
            &generate(&source, &grammar).with_context(|| grammar.clone())?,
            root,
        )?;
        let file = root.join(&output);
        if check {
            match std::fs::read_to_string(&file) {
                Ok(current) if current == text => {}
                Ok(_) => problems.push(format!("{output}: differs from what {grammar} generates")),
                Err(_) => problems.push(format!("{output}: missing")),
            }
        } else if std::fs::read_to_string(&file).ok().as_deref() != Some(&text) {
            if let Some(parent) = file.parent() {
                std::fs::create_dir_all(parent)?;
            }
            std::fs::write(&file, text).with_context(|| format!("write {}", file.display()))?;
            println!("wrote {output}");
        }
    }
    Ok(problems)
}

/// `code` through the repository's rustfmt (the pinned toolchain's, with the
/// repository's `rustfmt.toml`, found from `root`).
fn format_rust(code: &str, root: &Path) -> Result<String> {
    let mut child = Command::new("rustfmt")
        .args(["--edition", "2024", "--emit", "stdout"])
        .current_dir(root)
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .spawn()
        .context("run rustfmt")?;
    child
        .stdin
        .take()
        .context("rustfmt has no stdin")?
        .write_all(code.as_bytes())?;
    let out = child.wait_with_output()?;
    if !out.status.success() {
        bail!("rustfmt: {}", String::from_utf8_lossy(&out.stderr));
    }
    Ok(String::from_utf8(out.stdout)?)
}

/// The Rust of `ast.rs` for the grammar `source` (read from `origin`), not
/// yet formatted.
pub fn generate(source: &str, origin: &str) -> Result<String> {
    let grammar: Grammar = source.parse().map_err(|error| anyhow!("{error}"))?;
    let mut nodes = String::new();
    let mut rules = String::new();
    let mut uses_tokens = false;
    let mut uses_children = false;
    let mut uses_support = false;
    for node in grammar.iter() {
        let name = &grammar[node].name;
        if let Some(members) = enum_members(&grammar, node) {
            leaves(&grammar, node, &mut Vec::new())?;
            nodes += &emit_enum(&grammar, name, &members);
            continue;
        }
        let fields = fields(&grammar, node).with_context(|| format!("node `{name}`"))?;
        uses_tokens |= fields
            .iter()
            .any(|f| !matches!(f.shape, Shape::Node { .. }));
        uses_support |= !fields.is_empty();
        uses_children |= fields
            .iter()
            .any(|f| matches!(f.shape, Shape::Node { many: true, .. }));
        nodes += &emit_struct(&grammar, node, &fields);
        let mut leaves = BTreeSet::new();
        let rule = rule_expr(&grammar, &grammar[node].rule, &mut Vec::new(), &mut leaves)
            .with_context(|| format!("node `{name}`"))?;
        uses_tokens |= !leaves.is_empty();
        rules += &format!(
            "NodeRule {{ kind: SyntaxKind::{} as u16, name: {name:?}, text: {:?}, rule: {rule} }},\n",
            upper_snake(name),
            render(&grammar, &grammar[node].rule, false),
        );
    }
    let t = if uses_tokens { ", T" } else { "" };
    let children = if uses_children { "AstChildren, " } else { "" };
    let support = if uses_support { ", support" } else { "" };
    Ok(format!(
        "{MARKER} from `{origin}`: do not edit.\n\
         //! The typed AST of `{origin}`, and its rules as data for\n\
         //! `opentide_parse::conformance`.\n\n\
         use opentide_parse::ast::{{{children}AstNode{support}}};\n\
         use opentide_parse::conformance::{{NodeRule, Rule}};\n\
         use crate::{{Lang, SyntaxKind, SyntaxNode, SyntaxToken{t}}};\n\n\
         {nodes}\
         /// What the children of each node kind must match.\n\
         pub static RULES: &[NodeRule] = &[\n{rules}];\n"
    ))
}

/// The members of `node` when it is a choice of nodes (`A = B | C`).
fn enum_members(grammar: &Grammar, node: Node) -> Option<Vec<Node>> {
    let Rule::Alt(alts) = &grammar[node].rule else {
        return None;
    };
    alts.iter()
        .map(|rule| match rule {
            Rule::Node(member) => Some(*member),
            _ => None,
        })
        .collect()
}

#[derive(Debug)]
enum Shape {
    /// A child node; `nth` is its place among the children of its type.
    Node { ty: String, nth: usize, many: bool },
    /// The first child token of one of these kinds.
    Tokens(Vec<Token>),
}

#[derive(Debug)]
struct Field {
    name: String,
    shape: Shape,
}

/// One place a node or token occurs in a rule.
struct Occurrence {
    label: Option<String>,
    target: Target,
    /// Under a `*`.
    many: bool,
    /// Under a `?`, a `*` or an alternative: it may be absent, so a count of
    /// the children before it is no index.
    loose: bool,
}

enum Target {
    Node(Node),
    Tokens(Vec<Token>),
}

fn occurrences(
    grammar: &Grammar,
    rule: &Rule,
    label: Option<&str>,
    (many, loose): (bool, bool),
    out: &mut Vec<Occurrence>,
) -> Result<()> {
    let occur = |target| Occurrence {
        label: label.map(str::to_owned),
        target,
        many,
        loose,
    };
    match rule {
        Rule::Labeled { label, rule } => match &**rule {
            Rule::Alt(alts) if alts.iter().all(|r| matches!(r, Rule::Token(_))) => {
                let tokens = alts
                    .iter()
                    .filter_map(|r| {
                        if let Rule::Token(t) = r {
                            Some(*t)
                        } else {
                            None
                        }
                    })
                    .collect();
                out.push(Occurrence {
                    label: Some(label.clone()),
                    target: Target::Tokens(tokens),
                    many,
                    loose,
                });
            }
            Rule::Seq(_) | Rule::Alt(_) => bail!(
                "label `{label}` names {}: label one node or token, or a choice of tokens",
                render(grammar, rule, false)
            ),
            inner => occurrences(grammar, inner, Some(label), (many, loose), out)?,
        },
        Rule::Node(node) => out.push(occur(Target::Node(*node))),
        Rule::Token(token) => out.push(occur(Target::Tokens(vec![*token]))),
        Rule::Seq(rules) => {
            for rule in rules {
                occurrences(grammar, rule, label, (many, loose), out)?;
            }
        }
        Rule::Alt(rules) => {
            for rule in rules {
                occurrences(grammar, rule, label, (many, true), out)?;
            }
        }
        Rule::Opt(rule) => occurrences(grammar, rule, label, (many, true), out)?,
        Rule::Rep(rule) => occurrences(grammar, rule, label, (true, true), out)?,
    }
    Ok(())
}

fn fields(grammar: &Grammar, node: Node) -> Result<Vec<Field>> {
    let mut found = Vec::new();
    occurrences(
        grammar,
        &grammar[node].rule,
        None,
        (false, false),
        &mut found,
    )?;
    let mut by_node: BTreeMap<Node, Vec<(usize, &Occurrence)>> = BTreeMap::new();
    // Each field with the place of its first occurrence, which orders them.
    let mut fields: Vec<(usize, Field)> = Vec::new();
    let mut seen_tokens = BTreeSet::new();
    for (at, occ) in found.iter().enumerate() {
        match &occ.target {
            Target::Node(n) => by_node.entry(*n).or_default().push((at, occ)),
            Target::Tokens(tokens) => {
                let name = match (&occ.label, tokens.as_slice()) {
                    (Some(label), _) => ident(label),
                    (None, [token]) => format!("{}_token", token_name(&grammar[*token].name)?),
                    (None, _) => bail!("an unlabeled choice of tokens"),
                };
                if seen_tokens.insert(name.clone()) {
                    fields.push((
                        at,
                        Field {
                            name,
                            shape: Shape::Tokens(tokens.clone()),
                        },
                    ));
                }
            }
        }
    }
    // Nodes whose castable sets overlap (an enum and a member, two enums
    // sharing one) are one type to `support::child`, which selects by
    // `can_cast`: they form one group, indexed together.
    let mut castable: BTreeMap<Node, BTreeSet<Node>> = BTreeMap::new();
    for n in by_node.keys() {
        castable.insert(*n, leaves(grammar, *n, &mut Vec::new())?);
    }
    let mut groups: Vec<Vec<Node>> = Vec::new();
    for n in by_node.keys() {
        let (touching, rest): (Vec<_>, Vec<_>) = groups
            .drain(..)
            .partition(|g| g.iter().any(|m| !castable[m].is_disjoint(&castable[n])));
        groups = rest;
        let mut merged = vec![*n];
        merged.extend(touching.into_iter().flatten());
        groups.push(merged);
    }
    for group in groups {
        group_fields(grammar, &group, &by_node, &castable, &mut fields)?;
    }
    fields.sort_by_key(|(at, _)| *at);
    let fields: Vec<Field> = fields.into_iter().map(|(_, field)| field).collect();
    let mut names = BTreeSet::new();
    for field in &fields {
        if !names.insert(&field.name) {
            bail!("two children are named `{}`: label one of them", field.name);
        }
    }
    Ok(fields)
}

/// The accessors of one group of overlapping node types (`fields`).
fn group_fields(
    grammar: &Grammar,
    group: &[Node],
    by_node: &BTreeMap<Node, Vec<(usize, &Occurrence)>>,
    castable: &BTreeMap<Node, BTreeSet<Node>>,
    fields: &mut Vec<(usize, Field)>,
) -> Result<()> {
    let mut occs: Vec<(usize, &Occurrence, Node)> = group
        .iter()
        .flat_map(|n| by_node[n].iter().map(move |(at, o)| (*at, *o, *n)))
        .collect();
    occs.sort_by_key(|(at, ..)| *at);
    let first = occs[0].0;
    let types: BTreeSet<Node> = occs.iter().map(|(.., n)| *n).collect();
    let ty_of = |n: Node| grammar[n].name.clone();
    let field = |name, n: Node, nth, many| Field {
        name,
        shape: Shape::Node {
            ty: ty_of(n),
            nth,
            many,
        },
    };
    if let [(_, occ, n)] = occs.as_slice() {
        let ty = ty_of(*n);
        let name = match (&occ.label, occ.many) {
            (Some(label), _) => ident(label),
            (None, true) => plural(&snake(&ty)),
            (None, false) => ident(&snake(&ty)),
        };
        fields.push((first, field(name, *n, 0, occ.many)));
    } else if types.len() == 1
        && occs.iter().all(|(_, o, _)| o.label.is_none())
        && occs.iter().any(|(_, o, _)| o.many)
    {
        let n = occs[0].2;
        fields.push((first, field(plural(&snake(&ty_of(n))), n, 0, true)));
    } else if occs
        .iter()
        .all(|(_, o, _)| o.label.is_some() && !o.many && !o.loose)
        && occs.iter().enumerate().all(|(i, (_, _, n))| {
            // The `nth` child castable to `n` is this occurrence only if
            // every earlier one is castable to `n` too.
            occs[..i]
                .iter()
                .all(|(.., m)| castable[m].is_subset(&castable[n]))
        })
    {
        for (at, occ, n) in &occs {
            let nth = occs.iter().take_while(|(a, ..)| a != at).count();
            let name = ident(occ.label.as_deref().unwrap_or_default());
            fields.push((*at, field(name, *n, nth, false)));
        }
    } else {
        let names: Vec<String> = types.iter().map(|n| format!("`{}`", ty_of(*n))).collect();
        bail!(
            "{} occur{} {} times, or overlap{}, and the generator cannot tell which child \
             is which: give each occurrence a label (`lhs:Expr rhs:Expr`, all required, none \
             repeated, each after only occurrences its type includes), or write the \
             accessors by hand",
            names.join(" and "),
            if names.len() == 1 { "s" } else { "" },
            occs.len(),
            if names.len() == 1 { "s" } else { "" },
        );
    }
    Ok(())
}

/// The node kinds a `can_cast` of `node` accepts: itself, or for a choice of
/// nodes the union of its members'. A choice that contains itself is refused.
fn leaves(grammar: &Grammar, node: Node, open: &mut Vec<Node>) -> Result<BTreeSet<Node>> {
    let Some(members) = enum_members(grammar, node) else {
        return Ok(BTreeSet::from([node]));
    };
    if open.contains(&node) {
        bail!("`{}` contains itself", grammar[node].name);
    }
    open.push(node);
    let mut out = BTreeSet::new();
    for member in members {
        out.extend(leaves(grammar, member, open)?);
    }
    open.pop();
    Ok(out)
}

fn emit_struct(grammar: &Grammar, node: Node, fields: &[Field]) -> String {
    let name = &grammar[node].name;
    let kind = upper_snake(name);
    let rule = render(grammar, &grammar[node].rule, false);
    let mut out = format!(
        "/// `{name} = {rule}`\n\
         #[derive(Clone, Debug, PartialEq, Eq, Hash)]\n\
         pub struct {name} {{\n    syntax: SyntaxNode,\n}}\n\n\
         impl AstNode for {name} {{\n\
         type Language = Lang;\n\
         fn can_cast(kind: SyntaxKind) -> bool {{ kind == SyntaxKind::{kind} }}\n\
         fn cast(syntax: SyntaxNode) -> Option<Self> {{\n\
         Self::can_cast(syntax.kind()).then_some(Self {{ syntax }})\n}}\n\
         fn syntax(&self) -> &SyntaxNode {{ &self.syntax }}\n}}\n\n"
    );
    if fields.is_empty() {
        return out;
    }
    out += &format!("impl {name} {{\n");
    for field in fields {
        let fname = &field.name;
        out += &match &field.shape {
            Shape::Node { ty, many: true, .. } => format!(
                "/// The `{ty}` children.\n\
                 pub fn {fname}(&self) -> AstChildren<{ty}> {{ support::children(&self.syntax) }}\n"
            ),
            Shape::Node { ty, nth: 0, .. } => format!(
                "/// The `{ty}` child.\n\
                 pub fn {fname}(&self) -> Option<{ty}> {{ support::child(&self.syntax) }}\n"
            ),
            Shape::Node { ty, nth, .. } => format!(
                "/// The `{ty}` child, number {nth} from 0 among the `{ty}` children.\n\
                 pub fn {fname}(&self) -> Option<{ty}> {{ support::nth_child(&self.syntax, {nth}) }}\n"
            ),
            Shape::Tokens(tokens) => {
                let kinds: Vec<String> = tokens
                    .iter()
                    .map(|t| format!("T![{}]", t_arg(&grammar[*t].name)))
                    .collect();
                let call = match kinds.as_slice() {
                    [one] => format!("support::token(&self.syntax, {one})"),
                    many => format!("support::token_in(&self.syntax, &[{}])", many.join(", ")),
                };
                format!(
                    "/// The token child.\npub fn {fname}(&self) -> Option<SyntaxToken> {{ {call} }}\n"
                )
            }
        };
    }
    out + "}\n\n"
}

fn emit_enum(grammar: &Grammar, name: &str, members: &[Node]) -> String {
    let variants = members
        .iter()
        .map(|m| &grammar[*m].name)
        .collect::<Vec<_>>();
    let nested = |m: &Node| enum_members(grammar, *m).is_some();
    let can_cast = variants
        .iter()
        .map(|v| format!("{v}::can_cast(kind)"))
        .collect::<Vec<_>>()
        .join(" || ");
    let arms = members
        .iter()
        .filter(|m| !nested(m))
        .map(|m| {
            let v = &grammar[*m].name;
            format!(
                "SyntaxKind::{} => Self::{v}({v} {{ syntax }}),\n",
                upper_snake(v)
            )
        })
        .collect::<Vec<_>>()
        .concat();
    let fallback = members
        .iter()
        .filter(|m| nested(m))
        .map(|m| {
            let v = &grammar[*m].name;
            format!("{v}::cast(syntax.clone()).map(Self::{v})")
        })
        .reduce(|a, b| format!("{a}.or_else(|| {b})"))
        .unwrap_or_else(|| "None".to_owned());
    let cast = if arms.is_empty() {
        format!("{fallback}\n")
    } else {
        format!(
            "let node = match syntax.kind() {{\n{arms}_ => return {fallback},\n}};\nSome(node)\n"
        )
    };
    let declared = variants
        .iter()
        .map(|v| format!("/// A `{v}`.\n{v}({v}),\n"))
        .collect::<Vec<_>>()
        .concat();
    let syntax = variants
        .iter()
        .map(|v| format!("Self::{v}(it) => it.syntax(),\n"))
        .collect::<Vec<_>>()
        .concat();
    let froms = variants
        .iter()
        .map(|v| format!("impl From<{v}> for {name} {{\nfn from(node: {v}) -> Self {{ Self::{v}(node) }}\n}}\n\n"))
        .collect::<Vec<_>>()
        .concat();
    format!(
        "/// `{name} = {}`\n\
         #[derive(Clone, Debug, PartialEq, Eq, Hash)]\n\
         pub enum {name} {{\n{declared}}}\n\n\
         impl AstNode for {name} {{\n\
         type Language = Lang;\n\
         fn can_cast(kind: SyntaxKind) -> bool {{ {can_cast} }}\n\
         fn cast(syntax: SyntaxNode) -> Option<Self> {{\n{cast}}}\n\
         fn syntax(&self) -> &SyntaxNode {{ match self {{\n{syntax}}} }}\n}}\n\n{froms}",
        variants
            .iter()
            .map(|v| v.as_str())
            .collect::<Vec<_>>()
            .join(" | "),
    )
}

/// The `Rule` expression of `rule`, enums expanded to the kinds they stand
/// for; `leaves` collects the tokens used.
fn rule_expr(
    grammar: &Grammar,
    rule: &Rule,
    open: &mut Vec<Node>,
    leaves: &mut BTreeSet<Token>,
) -> Result<String> {
    let list = |rules: &[Rule], open: &mut Vec<Node>, leaves: &mut BTreeSet<Token>| {
        rules
            .iter()
            .map(|r| rule_expr(grammar, r, open, leaves))
            .collect::<Result<Vec<_>>>()
            .map(|items| items.join(", "))
    };
    Ok(match rule {
        Rule::Labeled { rule, .. } => rule_expr(grammar, rule, open, leaves)?,
        Rule::Node(node) => match enum_members(grammar, *node) {
            Some(members) => {
                if open.contains(node) {
                    bail!("`{}` contains itself", grammar[*node].name);
                }
                open.push(*node);
                let alts = list(
                    &members.iter().map(|m| Rule::Node(*m)).collect::<Vec<_>>(),
                    open,
                    leaves,
                )?;
                open.pop();
                format!("Rule::Alt(&[{alts}])")
            }
            None => format!(
                "Rule::Kind(SyntaxKind::{} as u16)",
                upper_snake(&grammar[*node].name)
            ),
        },
        Rule::Token(token) => {
            leaves.insert(*token);
            format!("Rule::Kind(T![{}] as u16)", t_arg(&grammar[*token].name))
        }
        Rule::Seq(rules) => format!("Rule::Seq(&[{}])", list(rules, open, leaves)?),
        Rule::Alt(rules) => format!("Rule::Alt(&[{}])", list(rules, open, leaves)?),
        Rule::Opt(rule) => format!("Rule::Opt(&{})", rule_expr(grammar, rule, open, leaves)?),
        Rule::Rep(rule) => format!("Rule::Rep(&{})", rule_expr(grammar, rule, open, leaves)?),
    })
}

/// A rule as it is written in a `.ungram`.
fn render(grammar: &Grammar, rule: &Rule, nested: bool) -> String {
    match rule {
        Rule::Labeled { label, rule } => format!("{label}:{}", render(grammar, rule, true)),
        Rule::Node(node) => grammar[*node].name.clone(),
        Rule::Token(token) => format!("'{}'", grammar[*token].name),
        Rule::Seq(rules) => {
            let text = rules
                .iter()
                .map(|r| render(grammar, r, true))
                .collect::<Vec<_>>()
                .join(" ");
            if nested { format!("({text})") } else { text }
        }
        Rule::Alt(rules) => {
            let text = rules
                .iter()
                .map(|r| render(grammar, r, true))
                .collect::<Vec<_>>()
                .join(" | ");
            if nested { format!("({text})") } else { text }
        }
        Rule::Opt(rule) => format!("{}?", render(grammar, rule, true)),
        Rule::Rep(rule) => format!("{}*", render(grammar, rule, true)),
    }
}

/// What goes inside `T![..]` for a token.
fn t_arg(token: &str) -> String {
    if matches!(token, "(" | ")" | "[" | "]" | "{" | "}") {
        format!("'{token}'")
    } else {
        token.to_owned()
    }
}

/// The name of a token in an accessor.
fn token_name(token: &str) -> Result<String> {
    if token.chars().all(|c| c.is_ascii_alphanumeric() || c == '_') {
        return Ok(snake(token));
    }
    const NAMES: &[(&str, &str)] = &[
        ("(", "l_paren"),
        (")", "r_paren"),
        ("[", "l_brack"),
        ("]", "r_brack"),
        ("{", "l_curly"),
        ("}", "r_curly"),
        (",", "comma"),
        (";", "semicolon"),
        (":", "colon"),
        ("::", "coloncolon"),
        (".", "dot"),
        ("..", "dotdot"),
        ("...", "dotdotdot"),
        ("=", "eq"),
        ("==", "eqeq"),
        ("!=", "neq"),
        ("!", "bang"),
        ("<", "l_angle"),
        (">", "r_angle"),
        ("<=", "lteq"),
        (">=", "gteq"),
        ("+", "plus"),
        ("-", "minus"),
        ("*", "star"),
        ("/", "slash"),
        ("%", "percent"),
        ("|", "pipe"),
        ("||", "pipepipe"),
        ("&", "amp"),
        ("&&", "ampamp"),
        ("^", "caret"),
        ("~", "tilde"),
        ("?", "question"),
        ("@", "at"),
        ("#", "pound"),
        ("$", "dollar"),
        ("=>", "fat_arrow"),
        ("->", "thin_arrow"),
    ];
    NAMES
        .iter()
        .find(|(text, _)| *text == token)
        .map(|(_, name)| (*name).to_owned())
        .with_context(|| format!("no accessor name for the token '{token}': label it"))
}

/// `PipeExpr` as `pipe_expr`.
fn snake(name: &str) -> String {
    let chars: Vec<char> = name.chars().collect();
    let mut out = String::new();
    for (i, &c) in chars.iter().enumerate() {
        if c.is_ascii_uppercase() && i > 0 {
            let prev = chars[i - 1];
            let next_lower = chars.get(i + 1).is_some_and(char::is_ascii_lowercase);
            if prev.is_ascii_lowercase()
                || prev.is_ascii_digit()
                || (prev.is_ascii_uppercase() && next_lower)
            {
                out.push('_');
            }
        }
        out.push(c.to_ascii_lowercase());
    }
    out
}

/// `PipeExpr` as `PIPE_EXPR`.
fn upper_snake(name: &str) -> String {
    snake(name).to_ascii_uppercase()
}

/// A name that is a Rust keyword, made an identifier.
fn ident(name: &str) -> String {
    // Strict, reserved and 2024-edition keywords.
    const KEYWORDS: &[&str] = &[
        "as", "async", "await", "break", "const", "continue", "dyn", "else", "enum", "extern",
        "false", "fn", "for", "gen", "if", "impl", "in", "let", "loop", "match", "mod", "move",
        "mut", "pub", "ref", "return", "static", "struct", "trait", "true", "try", "type",
        "unsafe", "use", "where", "while", "abstract", "become", "box", "do", "final", "macro",
        "override", "priv", "typeof", "unsized", "virtual", "yield",
    ];
    // Keywords that cannot be raw identifiers.
    const NO_RAW: &[&str] = &["self", "Self", "crate", "super"];
    if NO_RAW.contains(&name) {
        format!("{name}_")
    } else if KEYWORDS.contains(&name) {
        format!("r#{name}")
    } else {
        name.to_owned()
    }
}

/// The default accessor name of a repeated node; a label names it otherwise.
fn plural(name: &str) -> String {
    let consonant_y = name.ends_with('y')
        && name
            .chars()
            .rev()
            .nth(1)
            .is_some_and(|c| !"aeiou".contains(c));
    if consonant_y {
        format!("{}ies", &name[..name.len() - 1])
    } else if ["s", "x", "z", "ch", "sh"]
        .iter()
        .any(|e| name.ends_with(e))
    {
        format!("{name}es")
    } else {
        format!("{name}s")
    }
}
